-- Speglar det som lades på databasen 2026-09-22 via apply_migration i 28 delar
-- (kq2_inch_clean_q_kje_part_01 … _28), delade med scripts/split-migration.py:
--   part_01     (familjen kq2, backup kq2_before_20260921, schema, familjens rad, parametrar)
--   part_02     (värdelista, rensning av regler)
--   part_03–27  (regler 1–450 i satser om 8, dokumentkarta, produkterna KQ2H06-00A … KQ2H08-02AS)
--   part_28     (produkterna KQ2L06-01AS och KQ2T06-00A; max_pressure_bar bort)
-- Ersätter 20260916150000 (bara metrisk slang) med tumslangens kapitel, Q, KJE (J),
-- Clean (10-) och specialutförandena -X12/-X35/-X41.
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts kq2,
-- scripts/fingerprint-values.py):
--   regler 450   md5 c8de5d7067e30846e9f0eb229b4eb64c   villkor a2d68fef70ae4a98cef38d43f6ee4483
--   värden 107   md5 ccb53eedda6c001a094bb67728a89006
--   schema       md5 9f5046620518a29d0ce8ea634b66b2f3
-- Verifierat live: /sv/configurator/kq2 bygger KQ2H05-34AS1 (tumslang med NPT1/8, sida 31),
-- KQ2H05-32A1 (10-32 UNF), KQ2N01-03 (reducernippel till ø5/32", sida 152), 10-KQ2H06-02NS1
-- (Clean, sida 28), KQ2L08-01AQS (Q, sida 132), KQ2E04-00AJ (KJE, sida 129), KQ2H06-01AS1-X12,
-- KQ2L06-01A-X35, KQ2T07-09A och KQ2W13-37NP; stoppar KQ2N01-03A (nippeln skrivs utan
-- material), 10-KQ2H06-02AS (Clean kräver N), KQ2L06-01AQ (Q bara ø8/R1/8), KQ2E08-00AJ
-- (J bara ø2–ø6 och ø1/8"/ø5/32"/ø1/4") och KQ2H06-01A-X35 (-X35 inte för H).
--
-- KQ2: beställnyckeln enligt SMC One-touch Fittings KQ2 Series (CAT.ES50-37D, sida 6 och 102).
-- GENERERAD ur src/lib/catalog/kq2.ts och kq2-models.ts -- redigera inte för hand.
--
-- Familjen kq2 i kategorin fitting: {clean}KQ2{typ}{slang}-{port}{material}{q}{tätning}{kje}{knapp}{special},
-- t.ex. KQ2H06-01AS1 (nyckelns exempel sida 6), KQ2H06-01AS (sida 102),
-- KQ2H05-34AS1 (tumslang med NPT1/8, sida 31), 10-KQ2H06-02NS1 (Clean, sida 28),
-- KQ2L08-01AQS (Q, sida 132) och KQ2E04-00AJ (KJE, sida 129). 32 kopplingstyper,
-- åtta metriska och sju tumslangmått, 49 portar, tre material, två tätningar,
-- oval knapp, Q, J, Clean och tre specialutföranden; 2 846 modellnummer ur
-- måttabellerna styr vilka kombinationer som finns. Pluggen KQ2P-□□ har egen
-- kodform och är inte med.
--
-- De nio produktraderna får SMC-prefix, den nya nyckelns materialbokstav
-- (KQ2H06-01S -> KQ2H06-01AS, KQ2T06-00 -> KQ2T06-00A) och rätt gänga
-- (portkoden 01 är R1/8, inte G1/8).

begin;


insert into configurator_families (slug, name, title, description, category_slug)
values ('kq2', 'KQ2', 'KQ2', '', 'fitting')
on conflict (slug) do update set name = excluded.name;


create schema if not exists backup;
create table if not exists backup.kq2_before_20260921 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'kq2'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'kq2'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'kq2';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-KQ2-V1', '{"version":"1.0","steps":[{"id":"type","step":1,"title_sv":"Kopplingstyp","title_en":"Fitting type","required":true,"type":"single_select","options":[{"v":"H","label":"Rak: hankoppling (gänga), rak skarv (00) eller reducerad rak (slangmått)"},{"v":"S","label":"Rak hankoppling med insexfattning"},{"v":"F","label":"Rak honkoppling (Rc, M, G)"},{"v":"L","label":"Vinkel: hankoppling, vinkelskarv (00), instick (99) eller reducerad vinkel"},{"v":"LU","label":"Grenvinkel: han (gänga) eller skarv (00); bara rund knapp"},{"v":"K","label":"45° hankoppling"},{"v":"V","label":"Svivelvinkel, han"},{"v":"VS","label":"Svivelvinkel, han, med insexfattning"},{"v":"VF","label":"Svivelvinkel, hon"},{"v":"LF","label":"Vinkel honkoppling (Rc, M)"},{"v":"VD","label":"Dubbel svivelvinkel, han"},{"v":"VT","label":"Trippel svivelvinkel, han"},{"v":"Z","label":"Gren-svivelvinkel, han; bara rund knapp"},{"v":"ZF","label":"Gren-svivelvinkel, hon; bara rund knapp"},{"v":"ZD","label":"Dubbel gren-svivelvinkel, han; bara rund knapp"},{"v":"ZT","label":"Trippel gren-svivelvinkel, han; bara rund knapp"},{"v":"W","label":"Förlängd vinkel: han (gänga) eller instick (99)"},{"v":"T","label":"T: han-T (gänga), T-skarv (00) eller reducerad T (slangmått)"},{"v":"Y","label":"Han-T i löpriktningen (run tee)"},{"v":"D","label":"Delta: han-delta (gänga) eller delta-skarv (00)"},{"v":"TW","label":"Korsskarv (00)"},{"v":"TX","label":"Reducerad korsskarv, typ X (slangmått)"},{"v":"TY","label":"Reducerad korsskarv, typ Y (slangmått)"},{"v":"U","label":"Y: han-Y (gänga), Y-skarv (00), instick-Y (99) eller reducerad Y-skarv; bara rund knapp"},{"v":"UD","label":"Reducerad gren-Y; bara rund knapp"},{"v":"X","label":"Reducerad instick-Y; bara rund knapp"},{"v":"XD","label":"Dubbel instick-Y; bara rund knapp"},{"v":"R","label":"Instick-reducering (slangmått)"},{"v":"E","label":"Skottgenomföring: skarv (00) eller hankoppling (Rc/G)"},{"v":"LE","label":"Skottgenomföring, vinkelskarv (00)"},{"v":"N","label":"Nippel (99), reducernippel (slangmått) eller adapter (gänga); bara rund knapp"},{"v":"C","label":"Slanglock (00)"}]},{"id":"tube","step":2,"title_sv":"Slangens ytterdiameter","title_en":"Tubing O.D.","required":true,"type":"single_select","options":[{"v":"02","label":"ø2 mm"},{"v":"23","label":"ø3,2 mm"},{"v":"04","label":"ø4 mm"},{"v":"06","label":"ø6 mm"},{"v":"08","label":"ø8 mm"},{"v":"10","label":"ø10 mm"},{"v":"12","label":"ø12 mm"},{"v":"16","label":"ø16 mm"},{"v":"01","label":"ø1/8\" (tum)"},{"v":"03","label":"ø5/32\" (tum)"},{"v":"05","label":"ø3/16\" (tum)"},{"v":"07","label":"ø1/4\" (tum)"},{"v":"09","label":"ø5/16\" (tum)"},{"v":"11","label":"ø3/8\" (tum)"},{"v":"13","label":"ø1/2\" (tum)"}]},{"id":"port","step":3,"title_sv":"Port: gänga, slang på andra sidan, skottgenomföring eller nippel","title_en":"Port: thread, tubing on the other side, bulkhead or nipple","required":true,"type":"single_select","options":[{"v":"M3","label":"M3 x 0,5 med gasket (bara rostfritt G)"},{"v":"M5","label":"M5 x 0,8 med gasket"},{"v":"M6","label":"M6 x 1,0 med gasket"},{"v":"01","label":"R1/8 (han) / Rc1/8 (hon)"},{"v":"02","label":"R1/4 (han) / Rc1/4 (hon)"},{"v":"03","label":"R3/8 (han) / Rc3/8 (hon); nippel N med tumslang: reducernippel till ø5/32\""},{"v":"04","label":"R1/2 (han) / Rc1/2 (hon)"},{"v":"G01","label":"G1/8 med plantätning"},{"v":"G02","label":"G1/4 med plantätning"},{"v":"G03","label":"G3/8 med plantätning"},{"v":"G04","label":"G1/2 med plantätning"},{"v":"U01","label":"Uni 1/8 (passar Rc, G, NPT, NPTF) med gasket"},{"v":"U02","label":"Uni 1/4 med gasket"},{"v":"U03","label":"Uni 3/8 med gasket"},{"v":"U04","label":"Uni 1/2 med gasket"},{"v":"32","label":"10-32 UNF med gasket (tumslang)"},{"v":"33","label":"NPT1/16 (tumslang)"},{"v":"34","label":"NPT1/8 (tumslang)"},{"v":"35","label":"NPT1/4 (tumslang)"},{"v":"36","label":"NPT3/8 (tumslang)"},{"v":"37","label":"NPT1/2 (tumslang)"},{"v":"00A","label":"Slang på båda sidor, samma mått (skarv)"},{"v":"99A","label":"Instick (rörände), samma mått"},{"v":"23A","label":"Slang ø3,2 på andra sidan (reducering)"},{"v":"04A","label":"Slang ø4 på andra sidan (reducering)"},{"v":"06A","label":"Slang ø6 på andra sidan (reducering)"},{"v":"08A","label":"Slang ø8 på andra sidan (reducering)"},{"v":"10A","label":"Slang ø10 på andra sidan (reducering)"},{"v":"12A","label":"Slang ø12 på andra sidan (reducering)"},{"v":"16A","label":"Slang ø16 på andra sidan (reducering)"},{"v":"03A","label":"Slang ø5/32\" på andra sidan (reducering, tum)"},{"v":"05A","label":"Slang ø3/16\" på andra sidan (reducering, tum)"},{"v":"07A","label":"Slang ø1/4\" på andra sidan (reducering, tum)"},{"v":"09A","label":"Slang ø5/16\" på andra sidan (reducering, tum)"},{"v":"11A","label":"Slang ø3/8\" på andra sidan (reducering, tum)"},{"v":"13A","label":"Slang ø1/2\" på andra sidan (reducering, tum)"},{"v":"00","label":"Skottgenomföring med slang på båda sidor (E, LE)"},{"v":"99","label":"Nippel, samma mått (N)"},{"v":"06","label":"Reducernippel till ø6 (N)"},{"v":"08","label":"Reducernippel till ø8 (N)"},{"v":"10","label":"Reducernippel till ø10 (N)"},{"v":"12","label":"Reducernippel till ø12 (N)"},{"v":"16","label":"Reducernippel till ø16 (N)"},{"v":"05","label":"Reducernippel till ø3/16\" (N, tum)"},{"v":"07","label":"Reducernippel till ø1/4\" (N, tum)"},{"v":"09","label":"Reducernippel till ø5/16\" (N, tum)"},{"v":"11","label":"Reducernippel till ø3/8\" (N, tum)"},{"v":"13","label":"Reducernippel till ø1/2\" (N, tum)"}]},{"id":"material","step":4,"title_sv":"Gängmaterial (gängade kopplingar och skottgenomföringar)","title_en":"Thread material (threaded fittings and bulkheads)","required":false,"type":"single_select","options":[{"v":"A","label":"Mässing"},{"v":"N","label":"Mässing, kemiskt förnicklad"},{"v":"G","label":"Rostfritt stål 303 (bara M3)"}]},{"id":"seal","step":5,"title_sv":"Tätning på R-gängan (standard är utan)","title_en":"Seal on the R thread (none is standard)","required":false,"type":"single_select","options":[{"v":"S","label":"Tätningsmedel på R-gängan"},{"v":"P","label":"Plantätning på R-gängan (face seal)"}]},{"id":"button","step":6,"title_sv":"Frigöringsknapp (standard är rund)","title_en":"Release button (round is standard)","required":false,"type":"single_select","options":[{"v":"1","label":"Oval frigöringsknapp (ø3,2, ø4, ø6; standard är rund)"}]},{"id":"q","step":7,"title_sv":"Q-utförande (ø8/R1/8, KQ-seriens area)","title_en":"Q type (ø8/R1/8, KQ series effective area)","required":false,"type":"single_select","options":[{"v":"Q","label":"Q: KQ-seriens effektiva area (ø8 med R1/8; L, K, LF, W, T, Y)"}]},{"id":"kje","step":8,"title_sv":"KJE-utbytbar skottgenomföring","title_en":"KJE-interchangeable bulkhead union","required":false,"type":"single_select","options":[{"v":"J","label":"J: skottgenomföring utbytbar mot KJE (E, 00; ø2–ø6, ø1/8\", ø5/32\", ø1/4\")"}]},{"id":"clean","step":9,"title_sv":"Clean-serien (prefix 10-)","title_en":"Clean series (prefix 10-)","required":false,"type":"single_select","options":[{"v":"10-","label":"Clean-serien: förnicklat, fluorfett, renrumsblåst, dubbelförpackad"}]},{"id":"mto","step":10,"title_sv":"Specialutförande (-X)","title_en":"Made to order (-X)","required":false,"type":"single_select","options":[{"v":"-X12","label":"-X12: vit frigöringsknapp, vit vaselin"},{"v":"-X35","label":"-X35: svart kropp, ljusgrå/orange knapp"},{"v":"-X41","label":"-X41: fast strypning (fråga SMC om tillgänglighet)"}]}]}'::jsonb,
        'SMC KQ2 snabbkoppling, metrisk slang och tum', 'SMC KQ2 One-touch fitting, metric and inch tubing', 'fitting')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Snabbkopplingar KQ2 för slang ø2–ø16 och ø1/8"–ø1/2": gängade (M, R/Rc, G, Uni, UNF, NPT), skarvar, instick, reduceringar, nipplar och slanglock',
  description = 'SMC KQ2 One-touch fittings for metric tubing ø2–ø16 and inch tubing ø1/8"–ø1/2": 32 body types (male/female connectors, elbows, universal elbows, tees, run tees, Y, delta, cross, bulkheads, reducers, nipples, tube caps), threads M3/M5/M6 with gasket, R/Rc 1/8–1/2 and NPT 1/16–1/2 with sealant (S) or face seal (P), G 1/8–1/2 with face seal, Uni 1/8–1/2 and 10-32 UNF with gasket, brass (A), nickel-plated brass (N) or stainless 303 (G, M3 only), round or oval (1) release button, Clean series (10-), Q type (ø8/R1/8), KJE-interchangeable bulkhead (J) and made-to-order -X12/-X35/-X41. −100 kPa to 1 MPa, −5…60 °C. The plug KQ2P is not included.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = '{clean}KQ2{type}{tube}-{port}{material}{q}{seal}{kje}{button}{mto}',
  rules_schema_id = 'SCHEMA-KQ2-V1'
where slug = 'kq2';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'kq2';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'kq2';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"type","label":"Kopplingstyp","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"tube","label":"Slangens ytterdiameter","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"port","label":"Port: gänga, slang på andra sidan, skottgenomföring eller nippel","param_type":"select","sort_order":3,"required":true,"min_value":null,"max_value":null},{"param_key":"material","label":"Gängmaterial (gängade kopplingar och skottgenomföringar)","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"seal","label":"Tätning på R-gängan (standard är utan)","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"button","label":"Frigöringsknapp (standard är rund)","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"q","label":"Q-utförande (ø8/R1/8, KQ-seriens area)","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null},{"param_key":"kje","label":"KJE-utbytbar skottgenomföring","param_type":"select","sort_order":8,"required":false,"min_value":null,"max_value":null},{"param_key":"clean","label":"Clean-serien (prefix 10-)","param_type":"select","sort_order":9,"required":false,"min_value":null,"max_value":null},{"param_key":"mto","label":"Specialutförande (-X)","param_type":"select","sort_order":10,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'kq2';

insert into configurator_param_values (param_id, code, label, sort_order)
select p.id, r.code, r.label, r.sort_order
from jsonb_to_recordset('[{"param_key":"type","code":"H","label":"Rak: hankoppling (gänga), rak skarv (00) eller reducerad rak (slangmått)","sort_order":0},{"param_key":"type","code":"S","label":"Rak hankoppling med insexfattning","sort_order":1},{"param_key":"type","code":"F","label":"Rak honkoppling (Rc, M, G)","sort_order":2},{"param_key":"type","code":"L","label":"Vinkel: hankoppling, vinkelskarv (00), instick (99) eller reducerad vinkel","sort_order":3},{"param_key":"type","code":"LU","label":"Grenvinkel: han (gänga) eller skarv (00); bara rund knapp","sort_order":4},{"param_key":"type","code":"K","label":"45° hankoppling","sort_order":5},{"param_key":"type","code":"V","label":"Svivelvinkel, han","sort_order":6},{"param_key":"type","code":"VS","label":"Svivelvinkel, han, med insexfattning","sort_order":7},{"param_key":"type","code":"VF","label":"Svivelvinkel, hon","sort_order":8},{"param_key":"type","code":"LF","label":"Vinkel honkoppling (Rc, M)","sort_order":9},{"param_key":"type","code":"VD","label":"Dubbel svivelvinkel, han","sort_order":10},{"param_key":"type","code":"VT","label":"Trippel svivelvinkel, han","sort_order":11},{"param_key":"type","code":"Z","label":"Gren-svivelvinkel, han; bara rund knapp","sort_order":12},{"param_key":"type","code":"ZF","label":"Gren-svivelvinkel, hon; bara rund knapp","sort_order":13},{"param_key":"type","code":"ZD","label":"Dubbel gren-svivelvinkel, han; bara rund knapp","sort_order":14},{"param_key":"type","code":"ZT","label":"Trippel gren-svivelvinkel, han; bara rund knapp","sort_order":15},{"param_key":"type","code":"W","label":"Förlängd vinkel: han (gänga) eller instick (99)","sort_order":16},{"param_key":"type","code":"T","label":"T: han-T (gänga), T-skarv (00) eller reducerad T (slangmått)","sort_order":17},{"param_key":"type","code":"Y","label":"Han-T i löpriktningen (run tee)","sort_order":18},{"param_key":"type","code":"D","label":"Delta: han-delta (gänga) eller delta-skarv (00)","sort_order":19},{"param_key":"typ