from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"==":[{"var":"clean"},"10-"]},{"==":[{"var":"material"},"A"]}]},"message_sv":"Clean-serien (10-) har förnicklade mässingsdelar: gängade kopplingar och skottgenomföringar beställs med N, inte A (sida 28, t.ex. 10-KQ2H06-02NS1).","message_en":"The Clean series (10-) has nickel-plated brass parts: threaded fittings and bulkheads are ordered with N, not A (page 28, e.g. 10-KQ2H06-02NS1).","goto_step":"kq2-material"},{"severity":"info","if_json":{"==":[{"var":"clean"},"10-"]},"message_sv":"Clean-serien: mässingsdelarna förnicklade, fluorfett, luftblåst i renrum, dubbelförpackad, vit resinkropp och knapp; slangkopplingar skrivs med A som vanligt (10-KQ2H06-00A1) (sida 28 och 49).","message_en":"Clean series: nickel-plated brass parts, fluorine grease, air blown in a clean room, double packaging, white resin body and button; tube fittings are written with A as usual (10-KQ2H06-00A1) (pages 28 and 49).","goto_step":"kq2-clean"},{"severity":"error","if_json":{"and":[{"==":[{"var":"q"},"Q"]},{"or":[{"not":{"in":[{"var":"type"},["L","K","LF","W","T","Y"]]}},{"!=":[{"var":"tube"},"08"]},{"!=":[{"var":"port"},"01"]}]}]},"message_sv":"Q-utförandet finns bara för ø8 med R1/8 (port 01) och typerna KQ2L/K/LF/W/T/Y (sida 132, t.ex. KQ2L08-01AQS).","message_en":"The Q type exists only for ø8 with R1/8 (port 01) and the types KQ2L/K/LF/W/T/Y (page 132, e.g. KQ2L08-01AQS).","goto_step":"kq2-q"},{"severity":"info","if_json":{"==":[{"var":"q"},"Q"]},"message_sv":"Q: effektiv area utbytbar med KQ-serien (den äldre serien) — för utbyte i befintliga anläggningar; material A eller N (sida 132).","message_en":"Q: effective area interchangeable with the KQ series (the previous series) — for replacement in existing installations; material A or N (page 132).","goto_step":"kq2-q"},{"severity":"error","if_json":{"and":[{"==":[{"var":"kje"},"J"]},{"or":[{"!=":[{"var":"type"},"E"]},{"!=":[{"var":"port"},"00"]},{"not":{"in":[{"var":"tube"},["02","23","04","06","01","03","07"]]}},{"==":[{"var":"button"},"1"]}]}]},"message_sv":"KJE-utbytbar (J) finns bara för skottgenomföringens skarv KQ2E□□-00□ med rund knapp i ø2 mm, ø3,2 mm, ø4 mm, ø6 mm, ø1/8\" (tum), ø5/32\" (tum) och ø1/4\" (tum) (sida 129 och 154).","message_en":"KJE-interchangeable (J) exists only for the bulkhead union KQ2E□□-00□ with the round button in ø2 mm, ø3.2 mm, ø4 mm, ø6 mm, ø1/8\" (inch), ø5/32\" (inch) and ø1/4\" (inch) (pages 129 and 154).","goto_step":"kq2-kje"},{"severity":"info","if_json":{"==":[{"var":"kje"},"J"]},"message_sv":"J: skottgenomföringen får KJE-seriens gänga (M7–M11 x 0,75) och passar KJE:s hål och muttrar (sida 129).","message_en":"J: the bulkhead union gets the KJE series thread (M7–M11 x 0.75) and fits KJE holes and nuts (page 129).","goto_step":"kq2-kje"},{"severity":"info","if_json":{"==":[{"var":"mto"},"-X12"]},"message_sv":"-X12: vit frigöringsknapp, vit vaselin — fråga SMC om mått och leveranstid (sida 28 och 132).","message_en":"-X12: white release button, white vaseline lubricant — contact SMC for dimensions and lead time (pages 28 and 132).","goto_step":"kq2-mto"},{"severity":"error","if_json":{"and":[{"==":[{"var":"mto"},"-X35"]},{"in":[{"var":"type"},["S","E","N","H","F","C"]]}]},"message_sv":"-X35 finns inte för KQ2S/E/N/H/F/C (insexkoppling, skottgenomföring, nippel, rak han-/honkoppling, slanglock) (sida 28, not 1).","message_en":"-X35 is not available for KQ2S/E/N/H/F/C (hexagon socket head connector, bulkhead, nipple, straight male/female connector, colour cap) (page 28, note 1).","goto_step":"kq2-mto"}]'::jsonb) r;

