update products set
  sku = 'SMC-KQ2H06-00A',
  name = 'SMC KQ2H06-00A rak skarv ø6 mm',
  description = 'SMC KQ2 One-touch straight union, ø6 mm tubing, round release button. −100 kPa to 1 MPa, −5…60 °C. Order code KQ2H06-00A (catalogue page 102).'
where sku = 'KQ2H06-00A';

update product_specs s set value = x.value
from products p, (values
  ('thread', ''),
  ('material', 'Kropp PBT/PP och mässing C3604 (gängdel), chuck och styrning rostfritt 304, tätning NBR'),
  ('max_pressure', '10'),
  ('temp_range', '-5…+60 (vatten 0…+40)')
) as x(key, value)
where s.product_id = p.id and p.sku = 'SMC-KQ2H06-00A' and s.key = x.key and s.key <> 'thread';

